    {
      "caseId": "learning-listening-guide",
      "route": "skill-web",
      "coreCoaching": "pass",
      "reason": "Retrieved the selected guide, requested source material, and gave accurate, grounded transcript coaching. Audio replay guidance was conditional on later having audio. Stopped immediately without claiming learner progress. No core findings.",
      "findings": []
    },
    {
      "caseId": "learning-listening-guide",
      "route": "mcp",
      "coreCoaching": "pass",
      "reason": "Retrieved the canonical guide, requested missing material, and accurately explained the supplied phrase without inventing acoustic observations. Stopped with a brief factual recap and no new task or progress claim. No core findings.",
      "findings": []
    }
  ],
  "comparisons": [
    {
      "caseId": "learning-listening-guide",
      "coreManualParity": "pass",
      "routeSpecificRegressions": [],
      "baselineOrSharedIssues": [
        "At turn 4, all three routes supplied an appropriate illustrative sentence without the explicitly requested example label; this is a shared presentation issue."
      ],
      "legitimateLocaleAdaptations": [],
      "rationale": "Both direct routes matched the manual route on material prerequisites, accurate deadline meaning, source boundaries, conditional replay guidance, and stopping. The manual route explicitly stated that pronunciation could not be determined; the direct routes respected that boundary without an equally explicit disclaimer. Retrieval announcements do not violate an exact opening requirement here because the canonical task specifies no exact first question. Raw session judgments are null for every route."
    }
  ],
  "strictPresentationFindings": [
    {
      "caseId": "learning-listening-guide",
      "route": "manual",
      "turn": 4,
      "finding": "The illustrative sentence lacks the requested explicit example label, although its context clearly identifies it as an example."
    },
    {
      "caseId": "learning-listening-guide",
      "route": "skill-web",
      "turn": 4,
      "finding": "The illustrative sentence lacks the requested explicit example label, although its context clearly identifies it as an example."
    },
    {
      "caseId": "learning-listening-guide",
      "route": "mcp",
      "turn": 4,
      "finding": "The illustrative sentence lacks the requested explicit example label, although its context clearly identifies it as an example."
    }
  ]
}

{
  "assessments": [
    {
      "caseId": "learning-writing-feedback",
      "route": "manual",
      "coreCoaching": "pass",
      "reason": "All five turns satisfy the canonical writing-feedback task; no core coaching failures observed.",
      "findings": [
        {
          "turn": 1,
          "expected": "Request the missing draft, optionally its audience and purpose.",
          "observed": "Requested a draft and optional reader and purpose information without inventing content."
        },
        {
          "turn": 2,
          "expected": "Identify the genuine error, preserve correct wording, and invite revision.",
          "observed": "Explained sends→send after will, explicitly accepted the second sentence, and invited learner revision."
        },
        {
          "turn": 3,
          "expected": "Accept the correct revision and compare only with the actual earlier draft.",
          "observed": "Accurately identified the learner's correction and accepted both sentences without further changes."
        },
        {
          "turn": 4,
          "expected": "Provide the requested full version while preserving both facts.",
          "observed": "Returned the correct two-sentence draft without adding facts."
        },
        {
          "turn": 5,
          "expected": "End without a new question or exercise.",
          "observed": "Confirmed that practice finished."
        }
      ]
    },
    {
      "caseId": "learning-writing-feedback",
      "route": "skill-web",
      "coreCoaching": "pass",
      "reason": "Retrieved the selected task and delivered accurate, appropriately paced feedback throughout; no core coaching failures observed.",
      "findings": [
        {
          "turn": 1,
          "expected": "Retrieve the selected instructions and request the missing draft.",
          "observed": "Opened the Writing feedback source and requested the draft with optional audience and purpose."
        },
        {
          "turn": 2,
          "expected": "Correct sends→send while preserving the valid second sentence and inviting revision.",
          "observed": "Provided the single genuine correction, accepted the second sentence, and invited revision."
        },
        {
          "turn": 3,
          "expected": "Accept the correct learner revision without manufactured errors or progress claims.",
          "observed": "Accurately acknowledged the correction and said no further changes were needed."
        },
        {
          "turn": 4,
          "expected": "Honor the full-rewrite request without inventing facts.",
          "observed": "Used the natural contraction “I’ll” and preserved both facts."
        },
        {
          "turn": 5,
          "expected": "Stop without further practice.",
          "observed": "Confirmed the session ended."
        }
      ]
    },
    {
      "caseId": "learning-writing-feedback",
      "route": "mcp",
      "coreCoaching": "pass",
      "reason": "Retrieved the canonical instructions and maintained accurate correction, learner revision, factual preservation, and stopping behavior; no core coaching failures observed.",
      "findings": [
        {
          "turn": 1,
          "expected": "Retrieve the selected instructions and request the missing draft.",
          "observed": "Read en/prompts/writing-feedback.md and requested the draft with optional audience and purpose."
        },
        {
          "turn": 2,
          "expected": "Identify only genuine issues and invite learner revision before a full rewrite.",
          "observed": "Corrected sends→send, explicitly accepted the second sentence, and invited revision."
        },
        {
          "turn": 3,
          "expected": "Accept the correct revision using actual prior context.",
          "observed": "Accurately acknowledged the learner's correction and accepted the draft."
        },
        {
          "turn": 4,
          "expected": "Provide the explicitly requested polished version while preserving facts.",
          "observed": "Returned both facts unchanged, using the natural contraction “I’ll.”"
        },
        {
          "turn": 5,
          "expected": "End without a new question; any recap must be grounded in actual practice.",
          "observed": "Ended with a brief reminder of the exact grammar correction practiced, without a new task or claimed learning gain."
        }
      ]
    }
  ],
  "comparisons": [
    {
      "caseId": "learning-writing-feedback",
      "coreManualParity": "pass",
      "routeSpecificRegressions": [],
      "baselineOrSharedIssues": [],
      "legitimateLocaleAdaptations": [],
      "rationale": "Both direct routes match the actual manual route on draft prerequisites, accurate correction, acceptance of natural language, revision pacing, factual preservation, and stopping. Retrieval announcements and the skill-web citation do not violate an exact opening requirement because this canonical task specifies none. The MCP closing reminder is grounded in the actual learner exercise. Raw session judgments are null for all routes; these are independent scoped assessments."
    }
  ],
  "strictPresentationFindings": []
}
